#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAXV 8          // maximum number of vertices (0..7)
#define MAXE 8          // maximum number of edges the original program accepts

static int adj[MAXV][MAXV];
static int colour[MAXV];
static bool found_cycle = false;

/* Depth‑first search that stops as soon as a cycle is found */
static void dfs(int v)
{
    if (found_cycle) return;          // early exit if a cycle is already known
    colour[v] = 1;                    // grey – vertex is on the recursion stack

    for (int w = 0; w < MAXV; ++w) {
        if (adj[v][w] == 0) continue; // no edge v→w
        if (colour[w] == 0) {
            dfs(w);
            if (found_cycle) return;
        } else if (colour[w] == 1) {
            /* back edge → directed cycle */
            found_cycle = true;
            return;
        }
    }
    colour[v] = 2;                    // black – vertex processing finished
}

int main(int argc, char *argv[])
{
    /* ---------- input validation ----------------------------------- */
    if ((argc - 1) % 2 != 0) {               // number of arguments after program name must be even
        puts("INVALID_INPUT");
        return 0;
    }

    int edge_cnt = (argc - 1) / 2;
    if (edge_cnt > MAXE) {                   // the original binary accepted at most 8 edges
        puts("INVALID_INPUT");
        return 0;
    }

    memset(adj, 0, sizeof(adj));

    for (int i = 0; i < edge_cnt; ++i) {
        /* The original program used strtol without checking the end pointer, so we do the same. */
        char *endptr; /* unused */
        long u = strtol(argv[1 + 2 * i], &endptr, 10);
        long v = strtol(argv[1 + 2 * i + 1], &endptr, 10);

        /* Vertices must be in the range [0,7]; negative values are rejected. */
        if (u < 0 || u >= MAXV || v < 0 || v >= MAXV) {
            puts("INVALID_INPUT");
            return 0;
        }
        adj[(int)u][(int)v] = 1;   // directed edge u -> v
    }

    /* ---------- cycle detection ------------------------------------ */
    memset(colour, 0, sizeof(colour));
    found_cycle = false;

    for (int v = 0; v < MAXV; ++v) {
        if (colour[v] == 0) {
            dfs(v);
            if (found_cycle) break;
        }
    }

    puts(found_cycle ? "CYCLE" : "ACYCLIC");
    return 0;
}
